// Synthetic emergency fixture set (TRD 8.5, UT-01). Written by the developer for B1; no real tenant text.
// Each item carries the expected tier from rules + uncertainty alone (no model). None may end `routine`.
import type { Tier } from '../../src/tiers';

export interface EmergencyItem {
  id: string;
  text: string | null;
  hasMedia?: boolean;
  afterHours?: boolean;
  label: Exclude<Tier, 'routine'>;
  group: string;
}

const make = (group: string, label: EmergencyItem['label'], texts: Array<string | null>, opts: Partial<EmergencyItem> = {}): EmergencyItem[] =>
  texts.map((text, i) => ({ id: `${group}-${String(i + 1).padStart(2, '0')}`, text, label, group, ...opts }));

